sp_widget.client_script:
api.controller = function($scope, $window, $timeout, spUtil) {
  var c = this;

  c.currentStep = 1;
  c.submitting = false;
  c.errorMessage = '';
  c.successMessage = '';

  c.form = {
    studentName: '',
    email: '',
    registerNumber: '',
    gender: '',
    mobile: '',
    altMobile: '',
    fatherName: '',
    fatherMobile: '',
    address: '',
    language: '',
    collegeName: '',
    degree: '',
    branch: '',
    currentYear: '',
    cgpa: '',
    backlogs: 0,
    passingYear: '',
    semester: '',
    skills: '',
    git: '',
    linkedin: '',
    portfolio: ''
  };

  c.setStep = function(step) {
    c.currentStep = step;
  };

  c.nextStep = function() {
    if (c.currentStep < 3) {
      c.currentStep++;
    }
  };

  c.prevStep = function() {
    if (c.currentStep > 1) {
      c.currentStep--;
    }
  };

  c.submitForm = function() {
    c.submitting = true;
    c.errorMessage = '';
    c.successMessage = '';

    c.server.get({
      action: 'registerStudent',
      form: c.form
    }).then(function(response) {
      c.submitting = false;

      if (response.data.success) {
        c.successMessage = "Account created successfully! Redirecting to dashboard...";

        // Immediate redirect to student dashboard
        $timeout(function() {
          $window.location.href = response.data.redirectUrl || '/nexora?id=student_dashboard';
        }, 400);
      } else {
        c.errorMessage = response.data.errorMessage || "Submission failed. Please check form inputs.";
      }
    }, function(error) {
      c.submitting = false;
      c.errorMessage = "Server error during submission.";
    });
  };
};

sp_widget.css:
/* =========================================
   NEXORA MULTI-STEP SIGNUP STYLES
   ========================================= */

.nx-signup-page {
  position: relative !important;
  width: 100% !important;
  min-height: 100vh !important;
  background: radial-gradient(circle at 50% 20%, #203854 0%, #182a3e 70%);
  font-family: "Poppins", "Segoe UI", Arial, sans-serif;
  display: flex !important;
  flex-direction: column !important;
  align-items: center !important;
  justify-content: flex-start !important;
  padding: 40px 20px !important;
  box-sizing: border-box !important;
  overflow-y: auto !important;
}

.nx-signup-container {
  width: 100%;
  max-width: 920px;
  background: rgba(24, 42, 62, 0.92);
  backdrop-filter: blur(12px);
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 20px;
  padding: 35px 45px;
  box-shadow: 0 20px 50px rgba(0, 0, 0, 0.45);
  box-sizing: border-box;
  margin: 20px auto;

  @media (max-width: 600px) {
    padding: 24px 20px;
  }
}

/* HEADER TITLE & LINK VISIBILITY */
.nx-signup-header {
  display: flex !important;
  align-items: center !important;
  justify-content: space-between !important;
  margin-bottom: 24px !important;
  width: 100% !important;
}

.nx-brand {
  color: #ffffff !important;
  font-size: 28px !important;
  font-weight: 800 !important;
  line-height: 1 !important;

  span {
    color: #f27457 !important;
  }
}

.nx-external-link a {
  color: #ffffff !important;
  font-size: 14px !important;
  text-decoration: none !important;
  font-weight: 500 !important;

  strong {
    color: #f27457 !important;
    font-weight: 700 !important;
    margin-left: 4px !important;
  }

  &:hover strong {
    text-decoration: underline !important;
  }
}

/* WELCOME HEADER */
.nx-welcome {
  margin-bottom: 25px;

  .nx-kicker {
    display: block;
    margin-bottom: 6px;
    color: #f27457;
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 2px;
  }

  h2 {
    margin: 0;
    color: #ffffff;
    font-size: 26px;
    font-weight: 750;
    line-height: 1.2;
  }

  p {
    margin: 6px 0 0;
    color: rgba(255, 255, 255, 0.65);
    font-size: 13px;
  }
}

/* STEPPER BARS */
.nx-stepper {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 30px;
  padding: 0 10px;
}

.nx-step {
  display: flex;
  align-items: center;
  gap: 10px;
  cursor: pointer;
  opacity: 0.45;
  transition: opacity 0.25s ease;

  &.active, &.completed {
    opacity: 1;
  }

  .nx-step-number {
    width: 32px;
    height: 32px;
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.1);
    color: #ffffff;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 13px;
    font-weight: 700;
    transition: all 0.25s ease;
  }

  &.active .nx-step-number {
    background: #f27457;
    color: #ffffff;
    box-shadow: 0 0 12px rgba(242, 116, 87, 0.4);
  }

  &.completed .nx-step-number {
    background: #10b981;
    color: #ffffff;
  }

  .nx-step-label {
    color: #ffffff;
    font-size: 13px;
    font-weight: 600;

    @media (max-width: 520px) {
      display: none;
    }
  }
}

.nx-step-line {
  flex: 1;
  height: 2px;
  background: rgba(255, 255, 255, 0.1);
  margin: 0 16px;
  transition: background 0.3s ease;

  &.active {
    background: #f27457;
  }
}

/* SLIDER CONTROLLER */
.nx-slider-window {
  width: 100%;
  overflow: hidden;
  position: relative;
  min-height: 380px;
}

.nx-slider-track {
  display: flex;
  width: 300%;
  transition: transform 0.4s cubic-bezier(0.25, 1, 0.5, 1);
  align-items: flex-start;
}

.nx-slide-tab {
  width: 33.3333%;
  flex-shrink: 0;
  box-sizing: border-box;
  padding: 0 8px;
}

.nx-form-section-header {
  color: #f27457;
  font-size: 13px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1.2px;
  margin-bottom: 20px;
  padding-bottom: 8px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
}

.nx-form-row {
  display: flex;
  gap: 20px;
  width: 100%;

  @media (max-width: 600px) {
    flex-direction: column;
    gap: 0;
  }
}

.nx-form-group {
  width: 100%;
  margin-bottom: 18px;

  &.half {
    flex: 1;
  }

  label {
    display: block;
    margin-bottom: 6px;
    color: rgba(255, 255, 255, 0.88);
    font-size: 12px;
    font-weight: 600;

    .nx-required {
      color: #f27457;
    }
  }
}

.nx-input-wrapper {
  position: relative;
  width: 100%;
}

.nx-input-icon {
  position: absolute;
  left: 14px;
  top: 50%;
  z-index: 2;
  transform: translateY(-50%);
  color: #8995a5;
  font-size: 14px;
  pointer-events: none;
}

.nx-form-control {
  width: 100% !important;
  height: 44px !important;
  padding: 0 14px 0 40px !important;
  background: #ffffff !important;
  border: 1px solid #ffffff !important;
  border-radius: 8px !important;
  color: #1f2937 !important;
  font-size: 13px !important;
  outline: none !important;
  box-shadow: none !important;
  transition: border-color 0.2s ease, box-shadow 0.2s ease;

  &::placeholder {
    color: #a5adba;
  }

  &:focus {
    border-color: #f27457 !important;
    box-shadow: 0 0 0 3px rgba(242, 116, 87, 0.18) !important;
  }
}

select.nx-select {
  appearance: none;
  cursor: pointer;
}

/* BUTTON ACTION BAR */
.nx-action-bar {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  margin-top: 24px;
}

.nx-btn-primary {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  height: 46px;
  background: #f27457;
  border: none;
  border-radius: 8px;
  color: #ffffff;
  font-size: 13px;
  font-weight: 700;
  cursor: pointer;
  transition: background-color 0.2s ease;

  &:hover:not(:disabled) {
    background: #e06346;
  }

  &:disabled {
    opacity: 0.45;
    cursor: not-allowed;
    background: #556272;
  }
}

.nx-btn-secondary {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  height: 46px;
  padding: 0 24px;
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: 8px;
  color: #ffffff;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  transition: background-color 0.2s ease;

  &:hover {
    background: rgba(255, 255, 255, 0.16);
  }
}

/* ALERTS */
.nx-login-alert {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 14px;
  padding: 10px 14px;
  border-radius: 8px;
  font-size: 12px;
}

.nx-error {
  background: rgba(220, 38, 38, 0.12);
  border: 1px solid rgba(248, 113, 113, 0.25);
  color: #fca5a5;
}

.nx-success {
  background: rgba(22, 163, 74, 0.12);
  border: 1px solid rgba(74, 222, 128, 0.25);
  color: #86efac;
}

sp_widget.script:
(function() {
  data.success = false;
  data.errorMessage = "";

  if (input && input.action === 'registerStudent') {
    var dataInput = input.form;

    if (!dataInput) {
      data.errorMessage = "No form data received from client.";
      return;
    }

    try {
      // EXACT TABLE NAME FROM YOUR INSTANCE
      var tableName = 'x_2065256_colleg_0_student'; 
      var gr = new GlideRecord(tableName);

      if (!gr.isValid()) {
        data.success = false;
        data.errorMessage = "Table '" + tableName + "' does not exist. Please check your table name in ServiceNow.";
        return;
      }

      gr.initialize();

      // Personal Info
      gr.setValue('student_name', dataInput.studentName);
      gr.setValue('email', dataInput.email);
      gr.setValue('register_number', dataInput.registerNumber);
      gr.setValue('gender', dataInput.gender);
      gr.setValue('mobile_number', dataInput.mobile);
      gr.setValue('alternate_mobile_number', dataInput.altMobile);
      gr.setValue('father_name', dataInput.fatherName);
      gr.setValue('father_mobile_number', dataInput.fatherMobile);
      gr.setValue('address', dataInput.address);
      gr.setValue('language', dataInput.language);

      // Academic Info
      gr.setValue('college_name', dataInput.collegeName);
      gr.setValue('degree', dataInput.degree);
      gr.setValue('branch', dataInput.branch);
      gr.setValue('current_year', dataInput.currentYear);
      gr.setValue('cgpa', dataInput.cgpa);
      gr.setValue('backlogs', dataInput.backlogs);
      gr.setValue('passing_year', dataInput.passingYear);
      gr.setValue('semester', dataInput.semester);

      // Placement & Profiles
      gr.setValue('skills', dataInput.skills);
      gr.setValue('git', dataInput.git);
      gr.setValue('linkedln', dataInput.linkedin);
      gr.setValue('portfolio', dataInput.portfolio);

      var sysId = gr.insert();

      if (sysId) {
        data.success = true;
        data.redirectUrl = '/nexora?id=student_dashboard';
      } else {
        data.success = false;
        data.errorMessage = "Failed to insert record into database.";
      }
    } catch (ex) {
      gs.error("Nexora Signup Error: " + ex.message);
      data.success = false;
      data.errorMessage = "Server Exception: " + ex.message;
    }
  }
})();
